#!/usr/bin/env bash
# Reproduce the real-validation numbers of 'zcal' (model-v2x-track/routed-g1z) from the checkpoints: realval-A/B inference of every used
# member with its committed post-processing, bag fusion, merge with model.yaml, official metric, comparison with
# validation/results/scorecard.json. Needs the prepared real validation data and the checkpoints. Generated by
# common/tools/reproduce_validation.py. Run on an idle GPU:
#   CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-g1z/test/reproduce_zcal_validation.sh
# The inference commands are independent: `python common/tools/reproduce_validation.py model-v2x-track/routed-g1z --tag zcal --jobs`
# prints them, one per line, for running several GPUs at once.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
mkdir -p model-v2x-track/routed-g1z/validation/output/repro_zcal
[ -s model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-g1v2_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v2 --ckpt model-v2x-track/pointpillars-g1v2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pointpillars-g1v2/test/postprocess.yaml --out model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-g1v2_val.json
[ -s model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-g1v2_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v2 --ckpt model-v2x-track/pointpillars-g1v2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pointpillars-g1v2/test/postprocess.yaml --out model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-g1v2_valB.json
[ -s model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-g1v3_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v3 --ckpt model-v2x-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pointpillars-g1v3/test/postprocess.yaml --out model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-g1v3_val.json
[ -s model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-g1v3_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v3 --ckpt model-v2x-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pointpillars-g1v3/test/postprocess.yaml --out model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-g1v3_valB.json
[ -s model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-ut_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pointpillars-ut/test/postprocess.yaml --out model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-ut_val.json
[ -s model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-ut_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pointpillars-ut/test/postprocess.yaml --out model-v2x-track/routed-g1z/validation/output/repro_zcal/pointpillars-ut_valB.json
python common/tools/reproduce_validation.py model-v2x-track/routed-g1z --tag zcal --score
